use std::fs
use std::collections::HashMap

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut bal: HashMap<string, int> = HashMap::new()
    let mut names: Vec<string> = []
    for line in text.lines() {
        let p: Vec<string> = line.split_whitespace().map(|x| x.to_string()).collect()
        if p.len() == 0 {
            continue
        }
        let cmd = p[0].clone()
        if cmd == "open" && p.len() >= 3 {
            let a: int = p[2].parse::<int>().unwrap_or(0)
            if a < 0 {
                println("error: invalid amount")
            } else if bal.contains_key(p[1]) {
                println("error: duplicate account")
            } else {
                bal.insert(p[1].clone(), a)
                names.push(p[1].clone())
                println("ok")
            }
        } else if cmd == "balance" && p.len() >= 2 {
            if bal.contains_key(p[1]) {
                println("{}", bal[p[1]])
            } else {
                println("error: unknown account {}", p[1])
            }
        } else if (cmd == "deposit" || cmd == "withdraw") && p.len() >= 3 {
            let a: int = p[2].parse::<int>().unwrap_or(0)
            if a <= 0 {
                println("error: invalid amount")
            } else if !bal.contains_key(p[1]) {
                println("error: unknown account {}", p[1])
            } else {
                let cur: int = bal[p[1]]
                if cmd == "deposit" {
                    bal.insert(p[1].clone(), cur + a)
                    println("ok")
                } else if cur < a {
                    println("error: insufficient funds")
                } else {
                    bal.insert(p[1].clone(), cur - a)
                    println("ok")
                }
            }
        } else if cmd == "transfer" && p.len() >= 4 {
            let a: int = p[3].parse::<int>().unwrap_or(0)
            if a <= 0 {
                println("error: invalid amount")
            } else if !bal.contains_key(p[1]) {
                println("error: unknown account {}", p[1])
            } else if !bal.contains_key(p[2]) {
                println("error: unknown account {}", p[2])
            } else if p[1] == p[2] {
                println("error: same account")
            } else {
                let f: int = bal[p[1]]
                let t: int = bal[p[2]]
                if f < a {
                    println("error: insufficient funds")
                } else {
                    bal.insert(p[1].clone(), f - a)
                    bal.insert(p[2].clone(), t + a)
                    println("ok")
                }
            }
        }
    }
    names.sort()
    for n in names {
        println("{} {}", n, bal[n])
    }
}

